edits.replacement:
  /* v16.xx, THE STYLING PASS, STAGE E: THE STASH AND THE SHOP. Item cells and shop cells as rounded tiles with a light from the
     top and a lift on hover; the tabs as rounded chips. The rarity border colours, sizes and every id are unchanged. */
  #root .cell, #root .vcell{ border-radius:8px; background:linear-gradient(180deg,rgba(127,146,216,.07) 0%,rgba(0,0,0,.34) 100%);
    box-shadow:inset 0 1px 0 rgba(255,255,255,.05); }
  #root .cell:hover, #root .vcell:hover{ background:linear-gradient(180deg,rgba(255,192,74,.14) 0%,rgba(0,0,0,.30) 100%); transform:translateY(-2px);
    box-shadow:0 6px 16px rgba(0,0,0,.35), inset 0 1px 0 rgba(255,255,255,.07); }
  #root .vcell.on{ background:linear-gradient(180deg,rgba(255,192,74,.22) 0%,rgba(255,192,74,.08) 100%); }
  #root .invtab{ border-radius:8px; }
  #root .vendgrid{ border-radius:10px; }
  #root .vdet{ border-radius:12px; box-shadow:0 16px 40px rgba(0,0,0,.40); }
</style>

check:
{v:'VER',what:'stage E of the styling pass: stash cells, shop cells and the tabs are rounded tiles, and the cells carry a light from the top',
 run:function(){
   var root=document.getElementById('root')||document.body, d=document.createElement('div'), bad=[], c, v, t, s;
   d.innerHTML='<div class="invgrid"><div class="cell c-common">x</div></div><div class="vendgrid"><div class="vcell">y</div></div><div class="invtab">z</div>';
   root.appendChild(d); c=d.querySelector('.cell'); v=d.querySelector('.vcell'); t=d.querySelector('.invtab');
   try{
     s=getComputedStyle(c); if(parseFloat(s.borderTopLeftRadius)<6) bad.push('stash cells are square ('+s.borderTopLeftRadius+')'); if(!/gradient/.test(s.backgroundImage)) bad.push('stash cells are flat');
     s=getComputedStyle(v); if(parseFloat(s.borderTopLeftRadius)<6) bad.push('shop cells are square ('+s.borderTopLeftRadius+')');
     s=getComputedStyle(t); if(parseFloat(s.borderTopLeftRadius)<6) bad.push('the tabs are square ('+s.borderTopLeftRadius+')');
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   finally{ try{ root.removeChild(d); }catch(_r){} }
   return bad.length?bad.join('; '):null; }},
